bool MagmaZoneCosts::validJsonOfField(size_t index,
                                      const std::string &fieldName,
                                      const Json::Value &pJson,
                                      std::string &err,
                                      bool isForCreation)
{
    switch(index)
    {

        case 0:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 1:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 2:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 3:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 24)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 24)";
                return false;
            }

            break;

        case 4:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 5:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 6:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 7:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 120)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 120)";
                return false;
            }

            break;

        case 8:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 64)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 64)";
                return false;
            }

            break;

        case 9:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 10:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        default:
            err="Internal error in the server";
            return false;
    }
    return true;
}

MagmaZones MagmaZoneCosts::getMagmaZones(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from magma_zones where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *zoneId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return MagmaZones(r[0]);
}

void MagmaZoneCosts::getMagmaZones(const DbClientPtr &clientPtr,
                                   const std::function<void(MagmaZones)> &rcb,
                                   const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from magma_zones where id = $1";
    *clientPtr << sql
               << *zoneId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(MagmaZones(r[0]));
                    }
               }
               >> ecb;
}

